{
  "assertions": [
    {
      "id": "A1",
      "type": "text_present",
      "value": "Pending approval",
      "description": "The target claim's status in MY CLAIMS reads Pending approval, i.e. it is in the approval queue rather than still Draft."
    },
    {
      "id": "A2",
      "type": "text_present",
      "value": "Submit this claim for approval?",
      "description": "The submission confirmation dialog was shown, so the claim was routed to the approver rather than left unsubmitted."
    },
    {
      "id": "A3",
      "type": "text_absent",
      "value": "This claim cannot be submitted yet:",
      "description": "No unresolved validation banner remains blocking the claim from submission."
    },
    {
      "id": "A4",
      "type": "text_present",
      "value": "Attached",
      "description": "Every receipt dated in the claim's period is attached to the claim (each matching receipt row shows Attached)."
    },
    {
      "id": "A5",
      "type": "text_present",
      "value": "Total",
      "description": "The EXPENSE LINES table shows a derived Total equal to the sum of the entered expense line amounts."
    },
    {
      "id": "A6",
      "type": "unverifiable",
      "description": "The claim's status must be re-read in a freshly opened or reloaded claim view to distinguish a saved Pending approval result from a transient one; the assertion language cannot perform that reopen, so the agent must do it and confirm the status persists."
    }
  ]
}

